Tool response:
Tool: get_active_lease
Description: Retrieve the active lease record for a given tenant at a specific unit within a property.
Parameters:
    {
      "type": "object",
      "properties": {
        "property_id": {
          "type": "integer",
          "description": "Internal ID of the property",
          "title": "Property Id"
        },
        "unit_number": {
          "type": "string",
          "description": "Unit number within the property",
          "title": "Unit Number"
        },
        "tenant_id": {
          "type": "integer",
          "description": "Internal ID of the tenant",
          "title": "Tenant Id"
        }
      },
      "required": [
        "property_id",
        "unit_number",
        "tenant_id"
      ]
    }

Tool response:
Tool: amend_lease
Description: Update the lease end date, monthly rent, and pet policy for the specified lease.
Records the amendment in the lease_amendments table.
Parameters:
    {
      "type": "object",
      "properties": {
        "lease_id": {
          "type": "integer",
          "description": "Internal ID of the lease to amend",
          "title": "Lease Id"
        },
        "new_end_date": {
          "type": "string",
          "title": "New End Date"
        },
        "new_monthly_rent": {
          "type": "number",
          "title": "New Monthly Rent"
        },
        "new_pet_policy": {
          "type": "string",
          "title": "New Pet Policy"
        },
        "new_pet_deposit": {
          "type": "number",
          "title": "New Pet Deposit"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "lease_id",
        "new_end_date",
        "new_monthly_rent",
        "new_pet_policy",
        "new_pet_deposit"
      ]
    }
